#!/usr/bin/env python3
"""
Reorder a resolution table to match a given order of structure ids.

Paste your data into the two variables below:

  ID_ORDER      -- flat list of ids, in the order you want the output in
                   e.g. ["2pmk", "5knj", "2gvd", ...]

  RESOLUTIONS   -- list of [id, resolution] pairs (list of lists), in any order
                   e.g. [["2pmk", 2.11], ["5knj", 2], ["2gvd", 1.2], ...]

The script does not silently drop or guess anything:
  - an id in ID_ORDER with no match in RESOLUTIONS gets 'NA'
  - an id appearing more than once in RESOLUTIONS is flagged (first value used,
    all values reported)
  - ids in RESOLUTIONS that never appear in ID_ORDER are reported separately
    (they are not written to the main output at all, since the output is
    ordered by ID_ORDER)

Output: reordered_resolutions.txt (tab-separated: id, resolution, flag)
        reordered_resolutions.report.txt (counts + anomalies)
"""

