# --------------------------------------------------------------------------
from collections import defaultdict
 
OUTPUT = "reordered_resolutions.txt"
REPORT = "reordered_resolutions.report.txt"
 
 
def main():
    if not ID_ORDER:
        raise SystemExit("ID_ORDER is empty -- paste your id list into the script first.")
    if not RESOLUTIONS:
        raise SystemExit("RESOLUTIONS is empty -- paste your [id, resolution] pairs first.")
 
    # keyed by lowercased id; each value is a list of (original_id, value) pairs
    # so duplicates (including case-variant duplicates) keep their original casing
    res_by_id = defaultdict(list)
    for entry in RESOLUTIONS:
        if len(entry) != 2:
            raise SystemExit(f"RESOLUTIONS entry is not a 2-element [id, resolution] pair: {entry!r}")
        rid, value = entry
        res_by_id[rid.lower()].append((rid, value))
 
    dupes = {key: pairs for key, pairs in res_by_id.items() if len(pairs) > 1}
 
    id_order_set = {sid.lower() for sid in ID_ORDER}
    unmatched_res_ids = [pairs[0][0] for key, pairs in res_by_id.items() if key not in id_order_set]
 
    rows = []
    missing = []
    for sid in ID_ORDER:
        pairs = res_by_id.get(sid.lower())
        if pairs is None:
            rows.append((sid, "NA", "MISSING"))
            missing.append(sid)
        elif len(pairs) == 1:
            rows.append((sid, pairs[0][1], ""))
        else:
            rows.append((sid, pairs[0][1], "DUPLICATE"))
 
    with open(OUTPUT, "w", newline="") as f:
        f.write("id\tresolution\tflag\n")
        for sid, val, flag in rows:
            f.write(f"{sid}\t{val}\t{flag}\n")
 
    with open(REPORT, "w") as f:
        f.write(f"IDs in ID_ORDER: {len(ID_ORDER)}\n")
        f.write(f"Distinct ids in RESOLUTIONS: {len(res_by_id)}\n")
        f.write(f"Matched (resolution found): {len(ID_ORDER) - len(missing)}\n")
        f.write(f"Missing (no resolution): {len(missing)}\n\n")
 
        f.write(f"--- Missing ids ({len(missing)}) ---\n")
        f.write("\n".join(missing))
        f.write("\n\n")
 
        f.write(f"--- Duplicate ids within RESOLUTIONS ({len(dupes)}) ---\n")
        for key, pairs in dupes.items():
            f.write(f"{key}: {pairs}\n")
        f.write("\n")
 
        f.write(f"--- Ids in RESOLUTIONS not found in ID_ORDER ({len(unmatched_res_ids)}) ---\n")
        f.write("\n".join(unmatched_res_ids))
        f.write("\n")
 
    print(f"Wrote {len(rows)} rows to {OUTPUT}")
    print(f"Report written to {REPORT}")
 
 
if __name__ == "__main__":
    main()